import type { ComponentDoc, Json, PropDef } from '../core/model';
import { sampleOf, test } from '../core/model';
import { emitTree } from './jsx';
import { generateTypes, paramPattern } from './types';

export interface GeneratedFile {
  name: string;
  language: 'tsx' | 'ts';
  source: string;
}

const header = (component: ComponentDoc): string =>
  [
    '/**',
    ` * ${component.name}`,
    ...(component.description ? [` *`, ` * ${component.description}`] : []),
    ' *',
    ' * Generated by Nili Studio. Edit here once you own it.',
    ' */',
  ].join('\n');

function imports(nili: Set<string>, icons: Set<string>, reactNode: boolean): string {
  const lines: string[] = [];
  if (reactNode) lines.push("import type { ReactNode } from 'react';");
  if (icons.size) {
    lines.push(`import { ${[...icons].sort().join(', ')} } from '@remixicon/react';`);
  }
  if (nili.size) {
    const names = [...nili].sort();
    const single = `import { ${names.join(', ')} } from '@nili/ui';`;
    lines.push(
      single.length <= 80 ? single : `import {\n  ${names.join(',\n  ')},\n} from '@nili/ui';`,
    );
  }
  return lines.join('\n');
}

export function componentFile(component: ComponentDoc): GeneratedFile {
  const tree = emitTree(component);
  const types = generateTypes(component);
  const pattern = paramPattern(component);
  const signature = pattern
    ? `export function ${component.name}(${pattern}: ${types.propsType}) {`
    : `export function ${component.name}() {`;

  const source = [
    header(component),
    '',
    imports(tree.nili, tree.icons, types.usesReactNode),
    '',
    types.source,
    '',
    signature,
    '  return (',
    tree.jsx,
    '  );',
    '}',
    '',
  ].join('\n');

  return { name: `${component.name}.tsx`, language: 'tsx', source };
}

const argValue = (value: Json | undefined): string => JSON.stringify(value);

function argsFor(component: ComponentDoc, overrides: Record<string, Json> = {}): string[] {
  const values: Record<string, Json | undefined> = {};
  for (const prop of component.props) values[prop.name] = sampleOf(prop);
  Object.assign(values, overrides);

  const lines: string[] = [];
  for (const prop of component.props) {
    if (prop.kind === 'action' || prop.kind === 'node') continue;
    if (!test(prop.when, values)) continue;
    const value = values[prop.name];
    if (value === undefined) continue;
    if (value === prop.default && !prop.required) continue;
    lines.push(`    ${prop.name}: ${argValue(value)},`);
  }
  return lines;
}

const storyName = (name: string): string =>
  name.replace(/[^A-Za-z0-9]+(.)?/g, (_, c: string | undefined) => (c ? c.toUpperCase() : ''))
    .replace(/^./, (c) => c.toUpperCase()) || 'State';

export function storyFile(component: ComponentDoc): GeneratedFile {
  const base = argsFor(component);
  const stories = component.states.map((state) => {
    const args = argsFor(component, state.values);
    return [
      `export const ${storyName(state.name)}: Story = {`,
      args.length ? `  args: {\n${args.join('\n')}\n  },` : '  args: {},',
      '};',
    ].join('\n');
  });

  const source = [
    `import type { Meta, StoryObj } from '@storybook/react';`,
    `import { ${component.name} } from './${component.name}';`,
    '',
    `const meta: Meta<typeof ${component.name}> = {`,
    `  title: 'Studio/${component.name}',`,
    `  component: ${component.name},`,
    base.length ? `  args: {\n${base.join('\n')}\n  },` : null,
    '};',
    '',
    'export default meta;',
    'type Story = StoryObj<typeof meta>;',
    '',
    'export const Default: Story = {};',
    ...(stories.length ? ['', stories.join('\n\n')] : []),
    '',
  ]
    .filter((line): line is string => line !== null)
    .join('\n');

  return { name: `${component.name}.stories.tsx`, language: 'tsx', source };
}

/** A call site, so the API can be read without reading the implementation. */
export function usageFile(component: ComponentDoc): GeneratedFile {
  const values: Record<string, Json | undefined> = {};
  for (const prop of component.props) values[prop.name] = sampleOf(prop);

  const attrs = component.props
    .filter((prop: PropDef) => test(prop.when, values))
    .map((prop) => {
      if (prop.kind === 'action') return `  ${prop.name}={() => {}}`;
      if (prop.kind === 'node') return `  ${prop.name}={<span>…</span>}`;
      const value = values[prop.name];
      if (value === undefined || (value === prop.default && !prop.required)) return null;
      if (prop.kind === 'text') return `  ${prop.name}=${JSON.stringify(String(value))}`;
      return `  ${prop.name}={${JSON.stringify(value)}}`;
    })
    .filter((line): line is string => Boolean(line));

  const source = [
    `import { ${component.name} } from './${component.name}';`,
    '',
    'export function Example() {',
    '  return (',
    `    <${component.name}`,
    ...attrs.map((line) => `    ${line}`),
    '    />',
    '  );',
    '}',
    '',
  ].join('\n');

  return { name: 'usage.tsx', language: 'tsx', source };
}

export function generate(component: ComponentDoc): GeneratedFile[] {
  return [componentFile(component), storyFile(component), usageFile(component)];
}
